package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import com.lianxibu.site.repository.jobs.*;
import com.lianxibu.site.service.identity.IdentityService;
import com.lianxibu.site.service.jobs.UnknownCallRecoveryService.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;

/** Actual original day claim and unknown disposition to owner closure; no provider network. */
@EnabledIfEnvironmentVariable(named="B45_MYSQL",matches="true")
class OwnerJobCloseUnresolvedMySqlTest {
    SourceDayWorkerIntegrationMySqlTest f;WorkerAuthorizationService.Identity identity;OwnerJobCloseUnresolvedService service;
    final IdentityService.Actor owner=new IdentityService.Actor("fictional-owner","owner");long revision;
    @BeforeEach void setup()throws Exception{f=new SourceDayWorkerIntegrationMySqlTest();f.setup();f.db.jdbc.execute("ALTER TABLE jobs ADD error_code VARCHAR(64)");var claim=f.worker.claim(f.action());identity=claim.permit().identity();assertEquals(WorkerAuthorizationService.State.SENT,f.worker.dispatch(claim.permit(),json->"fictional-external-unknown").state());new TransportUnknownService(f.db.writes,new JdbcTransportUnknown(f.db.source),f.f.f.clock,"fictional-actual-day-worker").release(identity,TransportUnknownService.Cause.TRANSPORT_UNKNOWN,new SharedWriteExecutor.ActionContext("fictional-transport-unknown",f.root,null));revision=new JdbcJobRecords(f.db.source).byId(f.root).revision();service=new OwnerJobCloseUnresolvedService(f.db.writes,new JdbcOwnerJobClosureGuard(f.db.source),new UnknownCallJdbcStore(f.state,new JdbcWorkerRecovery(f.db.source,f.state),new JdbcJobRecords(f.db.source),"fictional-owner-close",ignored->false),f.f.f.clock);}
    OwnerJobCloseUnresolvedService.Closed close(String key){return service.close(owner,f.root,identity.attemptId(),revision,"Fictional unresolved closure",key);}
    @Test void unknownClosesToBlockedAndOriginalRevisionResponseDoesNotFollowCurrentChanges(){int rows=f.db.count("record_kind='ai_attempt'");var result=close("fictional-close!");assertEquals(State.CLOSED_UNRESOLVED,result.result().state());assertEquals(revision+1,result.revision());assertEquals(1,result.result().callCount());assertEquals("unknown",result.result().usageState());assertEquals("blocked",new JdbcJobRecords(f.db.source).byId(f.root).state());assertEquals("unknown_external",new JdbcJobRecords(f.db.source).byId(identity.attemptId()).state());assertEquals(rows,f.db.count("record_kind='ai_attempt'"));f.db.jdbc.update("UPDATE jobs SET revision=revision+1 WHERE id=?",f.root);assertEquals(result,close("fictional-close!"));assertEquals(1,f.db.count("target_type='worker_recovery'"));}
    @Test void originalUnknownClosureNeverFreesANewerSlot(){f.db.jdbc.update("UPDATE worker_lock SET slot_state='occupied',job_id='fictional-new-attempt',holder='fictional-new-worker',slot_revision=slot_revision+1,fencing_token=fencing_token+1");var before=f.state.slot();assertFalse(close("fictional-newer-slot").result().slotReleased());assertEquals(before,f.state.slot());assertEquals(1,new JdbcJobRecords(f.db.source).byId(f.root).callCount());}
    @Test void actualWrongRootAttemptRevisionAndOwnerRefuseWithoutAnyNewDisposition(){assertEquals(JobsService.JobRefusal.NOT_FOUND,assertThrows(JobsService.JobRejected.class,()->service.close(owner,"fictional-absent",identity.attemptId(),revision,"Fictional unresolved closure","fictional-wrong-root")).refusal());String other=f.f.day.original.plan.chunks().getFirst().rootId();assertEquals(JobsService.JobRefusal.RUN_FROZEN,assertThrows(JobsService.JobRejected.class,()->service.close(owner,other,identity.attemptId(),revision,"Fictional unresolved closure","fictional-other-root")).refusal());assertEquals(JobsService.JobRefusal.REVISION_CONFLICT,assertThrows(JobsService.JobRejected.class,()->service.close(owner,f.root,identity.attemptId(),revision+1,"Fictional unresolved closure","fictional-stale")).refusal());assertThrows(IdentityService.Rejected.class,()->service.close(new IdentityService.Actor("fictional-member","member"),f.root,identity.attemptId(),revision,"Fictional unresolved closure","fictional-role"));assertEquals(0,f.db.count("target_type='worker_recovery'"));}
    @Test void receiptFailureRollsBackRootAndDamagedOriginalClaimCannotClose(){f.db.jdbc.execute("ALTER TABLE jobs ADD CONSTRAINT fictional_owner_close_receipt CHECK(target_type IS NULL OR target_type<>'worker_recovery')");assertThrows(RuntimeException.class,()->close("fictional-receipt-fail"));assertEquals("unknown_external",new JdbcJobRecords(f.db.source).byId(f.root).state());assertEquals(revision,new JdbcJobRecords(f.db.source).byId(f.root).revision());f.db.jdbc.execute("ALTER TABLE jobs DROP CHECK fictional_owner_close_receipt");f.db.jdbc.update("UPDATE jobs SET action_payload_hash=? WHERE target_type='worker_claim'",new byte[32]);assertThrows(RuntimeException.class,()->close("fictional-damaged-claim"));assertEquals("unknown_external",new JdbcJobRecords(f.db.source).byId(f.root).state());assertEquals(0,f.db.count("target_type='worker_recovery'"));}
}
